library(creditratingsystem)
target<-list(event="default",horizon=1,time_unit="years",probability_measure="PHYSICAL",conditioning="performing")
training<-list(data_fingerprint="training-only-test",split_id="train",known_at="2025-01-01",data_origin="SYNTHETIC")
rows<-list(list(x=1,category="b"),list(x=NULL,category=NULL),list(x=3,category="a"))
schema<-list(list(name="x",type="numeric",imputation="median",scaling="standard",missing_indicator=TRUE),list(name="category",type="categorical",missing_policy="separate",unknown_policy="separate",drop_reference="a"))
fitted<-fit_preprocessor(rows,schema,target,training,"features","1")
query<-list(list(x=100,category="never_seen"),list(x=NULL,category=NULL))
transformed<-transform_features(query,fitted)
expected<-matrix(c(98/sqrt(2/3),0,0,0,1,0,1,0,1,0),2,byrow=TRUE)
stopifnot(max(abs(transformed$value$design_matrix-expected))<1e-12,fitted$model$parameters$feature_specs[[1]]$fill_value==2)
stopifnot(identical(do.call(rbind,lapply(query,function(row)transform_features(list(row),fitted)$value$design_matrix)),transformed$value$design_matrix))
allmissing<-fit_preprocessor(list(list(c=NULL)),list(list(name="c",type="categorical",missing_policy="separate",unknown_policy="separate")),target,training,"missing","1")
stopifnot(identical(transform_features(list(list(c=NULL),list(c="new")),allmissing)$value$design_matrix,matrix(c(1,0,0,1),2,byrow=TRUE)))
monotone<-fit_monotone_bins(c(1,1,2,3,4,5,NA),c(0,0,1,1,0,1,1),"x","increasing",1,6,target,training,"bins","1")
stopifnot(identical(unlist(head(monotone$model$parameters$upper_boundaries,-1)),c(1,4)),max(abs(vapply(monotone$model$parameters$bins,function(b)b$default_rate,numeric(1))-c(0,2/3,1,1)))<1e-14)
binned<-transform_features(list(list(x=-100),list(x=1),list(x=4),list(x=100),list(x=NULL)),monotone)
stopifnot(identical(as.numeric(binned$value$design_matrix),c(0,0,1,2,3)))
woe<-compute_woe_iv(list(list(bin_id="a",defaults=1,nondefaults=3),list(bin_id="b",defaults=3,nondefaults=1)),0,"nondefault_over_default")
stopifnot(abs(woe$value$iv-log(3))<1e-14,abs(woe$value$bins[[1]]$woe-log(3))<1e-14)
statements<-list(list(entity_id="a",as_of="2024-12-31",period_start="2024-01-01",period_end="2024-12-31",currency="EUR",values=list(cf=12,interest=2,principal=4),units=list(cf="EUR",interest="EUR",principal="EUR")))
specs<-list(list(name="dscr",numerator=list(cf=1),denominator=list(interest=1,principal=1),denominator_policy="positive",output_unit="dimensionless"))
ratios<-build_financial_ratios(statements,specs);stopifnot(ratios$value[[1]]$ratios$dscr$value==2)
series<-list(list(entity_id="a",feature="x",observed_at="2024-02-29",available_at="2024-03-01",known_at="2024-03-01",value=10),list(entity_id="a",feature="x",observed_at="2024-02-29",available_at="2024-04-02",known_at="2024-04-02",value=999),list(entity_id="a",feature="x",observed_at="2024-03-31",available_at="2024-03-31",known_at="2024-03-31",value=12))
observations<-list(list(entity_id="a",as_of="2024-03-31",known_at="2024-03-31"))
specs<-list(list(name="lag1",feature="x",lag=1,operation="level"),list(name="change",feature="x",lag=1,operation="relative_change"),list(name="gap",feature="x",lag=2,operation="level"))
lags<-build_distributed_lags(series,observations,specs,"months")
stopifnot(lags$value[[1]]$features$lag1==10,abs(lags$value[[1]]$features$change-.2)<1e-14,is.null(lags$value[[1]]$features$gap),!lags$value[[1]]$eligible)
expect_code<-function(expr,code){actual<-tryCatch({force(expr);"NO_ERROR"},creditratingsystem_error=function(e)e$code);stopifnot(identical(actual,code))}
expect_code(transform_features(list(list(x=1)),fitted),"MISSING_FEATURE")
expect_code(fit_preprocessor(list(list(x=NULL)),list(list(name="x",type="numeric",imputation="median",scaling="none")),target,training,"bad","1"),"NO_OBSERVED_VALUES")
path<-tempfile(fileext=".json");serialize_fitted_model(fitted,path);loaded<-load_fitted_model(path)
stopifnot(identical(transform_features(rows,loaded)$value$design_matrix,transform_features(rows,fitted)$value$design_matrix))
